async function downloadStatement(){const btn=root.querySelector('#baDownloadStatement'),notice=root.querySelector('#baStatementNotice'),from=root.querySelector('#baStatementFrom')?.value||'',to=root.querySelector('#baStatementTo')?.value||'';if(from&&to&&from>to){notice.textContent='The start date must be on or before the end date.';return}btn.disabled=true;btn.textContent='PREPARING PDF…';notice.textContent='';try{const r=await post('registerStatement',{statementType:'CLIENT',from,to,clientSessionToken:s.clientSessionToken,clientAccessToken:s.clientAccessToken,phone:s.phone});if(!r.statementReference||!r.integrityHash||!r.verificationUrl)throw new Error('BrightAce did not return the complete authenticated statement package. Please deploy the latest backend first.');await loadExternalScript('../js/statement-pdf.js');const tx=Array.isArray(r.transactions)?r.transactions:[];const incoming=tx.filter(x=>String(x.type||'').toUpperCase()==='PAYMENT'&&String(x.status||'').toUpperCase()==='PAID').reduce((n,x)=>n+Number(x.amount||0),0);const outgoing=tx.filter(x=>String(x.type||'').toUpperCase()==='REFUND'&&String(x.status||'').toUpperCase()==='APPROVED').reduce((n,x)=>n+Number(x.amount||0),0);const currency=String(tx.find(x=>x.currency)?.currency||'KES').toUpperCase();await window.BrightAceStatementPDF.download({title:'Official Client Financial Statement',subtitle:'BrightAce Academy • Paid Transactions & Refund Activity',statementReference:r.statementReference,integrityHash:r.integrityHash,verificationUrl:r.verificationUrl,generatedAt:r.generatedAt,party:r.party,transactions:tx,periodText:(r.range?.from||r.range?.to)?`${r.range?.from||'Start'} to ${r.range?.to||'Present'}`:'All recorded financial activity',summary:{currency,incoming,outgoing,net:incoming-outgoing,note:'Official BrightAce Academy record of paid transactions and refund activity.'},filename:`BrightAce-Client-Statement-${r.statementReference}.pdf`});notice.textContent='Statement downloaded successfully.';}catch(e){notice.textContent=e.message||'The client statement could not be downloaded.'}finally{btn.disabled=false;btn.textContent='⬇ DOWNLOAD STATEMENT'}}
      root.querySelector('#baDownloadStatement').onclick=downloadStatement;root.querySelector('#baOpenRefund').onclick=()=>openRefund();root.querySelector('#baRefundPayment').onchange=e=>{const o=e.target.selectedOptions[0],amount=Number(o?.dataset.amount||0),currency=o?.dataset.currency||'KES';root.querySelector('#baRefundAmount').value=amount>0?amount:'';root.querySelector('#baRefundPaymentLabel').textContent=o?.value?`Selected payment ${o.value} · ${currency} ${amount.toFixed(2)}. You can request a partial or full refund.`:'Choose a payment to continue.';root.querySelector('#baRefundNotice').textContent='';};root.querySelector('#baRefundClose').onclick=closeRefund;root.querySelector('#baRefundCancel').onclick=closeRefund;root.querySelector('#baRefundSubmit').onclick=submitRefund;root.querySelector('#baRefundModal').onclick=e=>{if(e.target.id==='baRefundModal')closeRefund()};root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');draw(b.dataset.tab)});draw('invoices');return;
